sys_script_include.script:
var trigger_enroll_workflow = Class.create();
trigger_enroll_workflow.prototype = {
    initialize: function() {},

    execute: function(ritm_sys_id) {
        var helper = new trigger_workflow_common();
        var context = {};
        var requestScript = 'new_certificate_request';

        try {
            context = helper.createContext(ritm_sys_id);
            var ritmGR = context.ritmGR;
            var form = context.form;
            var ca_tag_name = form.ca_tag_name;
            var gr_clm = helper.getClmSettings(ca_tag_name);
            var cert_content = helper.getUploadedContent(ritmGR, form.upload_csr);

            var upload_cert_content;
            if (form.csr_input_method == 'Upload CSR') {
                if (form.csr_upload_option == 'Paste CSR') {
                    upload_cert_content = (form.paste_csr).toString();
                } else {
                    upload_cert_content = (cert_content).toString();
                }
            }

            var groupDetails = helper.getAssignmentGroupDetails(ritmGR);
            var assignment_group_name = groupDetails.assignment_group_name;

            var san_values = [];
            gr_clm.add_dns_values = (form.add_dns_values).toString();
            gr_clm.add_ip_address = (form.add_ip_address).toString();
            gr_clm.add_email_address = (form.add_email_address).toString();
            if (gr_clm.add_dns_values === "true") {
                san_values.push("DNS");
            }
            if (gr_clm.add_ip_address === "true") {
                san_values.push("IP Address");
            }

            var cert_type;
            if (form.certificate_authority == 'DigiCert') {
                cert_type = (form.certificate_type).toString();
            } else if (form.certificate_authority == 'Entrust') {
                cert_type = (form.entrust_certificate_type).toString();
            } else if (form.certificate_authority == 'GoDaddy') {
                cert_type = (form.godaddy_certificate_type).toString();
            } else if (form.certificate_authority == 'Comodo Certificate Manager') {
                cert_type = (form.sectigo_certificate_type).toString();
            } else if (form.certificate_authority == 'GlobalSign') {
                cert_type = (form.globalsign_certificate_type).toString();
            } else if (form.certificate_authority == 'GlobalSignMSSL') {
                cert_type = (form.globalsign_mssl_certificate_type).toString();
            } else if (form.certificate_authority == 'Trustwave') {
                cert_type = (form.trustwave_certificate_type).toString();
            } else if (form.certificate_authority == 'HydrantID') {
                cert_type = (form.hydrantid_policy_name).toString();
            } else if (form.certificate_authority == 'SwissSign') {
                cert_type = (form.swisssign_product).toString();
            }

            var client_san;
            if (form.certificate_category == 'Client' && form.certificate_authority != 'Microsoft Enterprise') {
                san_values.push("Email Address");
                client_san = form.subject_alternative_name || '';
            } else if (form.certificate_authority == 'Microsoft Enterprise') {
                if (gr_clm.add_email_address === "true") {
                    san_values.push("Email Address");
                    client_san = form.san_email || '';
                }
            }

            var profile_name;
            if (form.push_to_end_device == 'true') {
                if (context.cmdb_sync == 'true') {
                    var profiles = form.profile_name_reference;
                    var profile_obj = new GlideRecord('x_avx_appviewx_aut_vendor_profiles_table');
                    profile_obj.addQuery('sys_id', 'IN', profiles);
                    profile_obj.query();
                    var profile_names = "";
                    while (profile_obj.next()) {
                        if (profile_names) {
                            profile_names = profile_names + "," + profile_obj.getValue('profile_name');
                        } else {
                            profile_names = profile_obj.getValue('profile_name');
                        }
                    }
                    profile_name = profile_names;
                } else {
                    profile_name = form.profile_name;
                }
            }

            var key_vault_name;
            if (form.push_to_end_device == 'true' && form.vendor_csr == 'Azure') {
                if (context.cmdb_sync == 'true') {
                    var akv_obj = new GlideRecord('x_avx_appviewx_aut_vendor_profiles_table');
                    akv_obj.addQuery('sys_id', 'IN', form.key_vault_name);
                    akv_obj.query();
                    var akv_names = "";
                    while (akv_obj.next()) {
                        if (akv_names) {
                            akv_names = akv_names + "," + akv_obj.getValue('key_vault_name');
                        } else {
                            akv_names = akv_obj.getValue('key_vault_name');
                        }
                    }
                    key_vault_name = akv_names;
                } else {
                    key_vault_name = form.key_vault_name;
                }
            }

            if (form.certificate_authority == 'DigiCert MPKI') {
                var custom_cert_attr = [];
                var custom_attributes = [];
                var digicert_mpki_profile = form.digicert_mpki_profiles;
                var digicert_mpki_ca_details = form.digicert_mpki_ca_details;
                var profile_names_mpki = JSON.parse(digicert_mpki_ca_details);
                profile_names_mpki = digicert_mpki_ca_details.endEntityProfiles;
                for (var itr = 0; itr < profile_names_mpki.length; itr++) {
                    if (profile_names_mpki[itr].profileName == digicert_mpki_profile) {
                        custom_attributes = profile_names_mpki[itr].customAttributes || [];
                        break;
                    }
                }
                var custom_attributes_length = custom_attributes.length;
                if (custom_attributes_length > 0) {
                    for (var meta_data = 1; meta_data < custom_attributes_length + 1; meta_data++) {
                        var custom_cert_attributes = {};
                        var field_name = custom_attributes[meta_data - 1].name;
                        var field_id = "custom_meta_data_" + (meta_data.toString());
                        custom_cert_attributes['custom_attribute'] = field_name;
                        custom_cert_attributes['custom_attribute_value'] = (form[field_id] || '').toString();
                        custom_cert_attr.push(custom_cert_attributes);
                    }
                }
            }

            var auto_renew = 'Off';
            var renew_before = '';
            var auto_regenerate = 'Off';
            var regenerate_before = '';
            var automatic_action = (gr_clm.automatic_certificate_action || '').toString();
            var days_before_expiry = (gr_clm.days_before_expiry || '').toString();

            if ((gr_clm.enable_automatic_renewal_regeneration || '').toString() == 'true') {
                if (automatic_action == 'Auto Renewal') {
                    auto_renew = 'On';
                    renew_before = days_before_expiry;
                } else if (automatic_action == 'Auto Regeneration') {
                    auto_regenerate = 'On';
                    regenerate_before = days_before_expiry;
                }
            }


            var cert_attr = helper.getCertificateAttributes(form, ritmGR, ca_tag_name, context.company, assignment_group_name);
            var fieldInfo = {
                "cert_category": (form.certificate_category || '').toString(),
                "certificate_policy": (form.certificate_policy || '').toString(),
                "certificate_group": (form.certificate_group || '').toString(),
                "certificate_authority": (form.certificate_authority).toString(),
                "input_method": (form.csr_input_method || '').toString(),
                "ca_account": (form.ca_account || '').toString(),
                "division": (form.division || '').toString(),
                "cert_type": (cert_type || '').toString(),
                "avx_pkiaas_native_isssuer_name": (form.issuer_name || '').toString(),
                "avx_pkiaas_native_template": (form.avx_template || '').toString(),
                "auto_renew": auto_renew,
                "renew_before": renew_before,
                "auto_regenerate": auto_regenerate,
                "regenerate_before": regenerate_before,
                "upload_csr": (upload_cert_content || '').toString(),
                "common_name": ((form.common_name || '').toString()).trim(),
                "san": (san_values.join(",") || '').toString(),
                "directory_names": "",
                "dns_names": (form.dns || '').toString(),
                "rfc822names": (client_san || '').toString(),
                "ip_addresses": (form.ip_address || '').toString(),
                "registered_ids": "",
                "uris": "",
                "othernames": "",
                "organization": (form.organization || '').toString(),
                "organization_unit": (form.organization_unit || '').toString(),
                "locality": (form.locality || '').toString(),
                "state": (form.state || '').toString(),
                "country": (form.country || '').toString(),
                "email_address": (form.email_address || '').toString(),
                "digicert_postal_code": "",
                "validity_unit": (form.validity_unit || '').toString(),
                "validity_value": (form.validity_value || '').toString(),
                "challenge_password": "",
                "hash_function": (form.hash_function || '').toString(),
                "key_type": (form.key_type || '').toString(),
                "bit_length": (form.bit_length || '').toString(),
                "sphincsKeyVersion": (form.key_version || '').toString(),
                "elliptic_curve": (form.ecdsa_curve || '').toString(),
                "digicert_server_type": (form.server_type || '').toString(),
                "ejbca_end_entity_profile_name": (form.ejbca_end_entity_profile_name || '').toString(),
                "ejbca_end_entity_user_name": (form.ejbca_end_entity_user_name || '').toString(),
                "ejbca_issuer_common_name": (form.ejbca_issuer_common_name || '').toString(),
                "ejbca_certificate_profile_name": (form.ejbca_certificate_profile_name || '').toString(),
                "entrust_additional_emails": "",
                "microsoft_enterprise_template_name": (form.microsoft_template || '').toString(),
                "user_email": (form.email_id || '').toString(),
                "sync_mode": "Sync",
                "ttl": "300",
                "appviewx_approval": (gr_clm.approval_levels_in_appviewx || '').toString(),
                "cert_format": ((form.certificate_issuance_format || '').toString()).trim(),
                "cert_issue_mode": (gr_clm.certificate_retrieval_mode || '').toString(),
                "requestor_id": (ritmGR.requested_for.email || '').toString(),
                "sys_id": (ritmGR.sys_id || '').toString(),
                "one_level_approver_mail_id": (gr_clm.appviewx_one_level_approval_mail_id_for_create || '').toString(),
                "two_level_approver_mail_id": (gr_clm.appviewx_two_level_approval_mail_id_for_create || '').toString(),
                "ritm_number": (ritmGR.number || '').toString(),
                "req_number": (ritmGR.request.getDisplayValue() || '').toString(),
                "req_sys_id": (ritmGR.request || '').toString(),
                "cert_attributes": (cert_attr || []),
                "appviewx_url": context.url.toString(),
                "certificate_group_selection": (gr_clm.certificate_group_selection || '').toString(),
                "servicenow_user_name": (ritmGR.requested_for.name || '').toString(),
                "amazonCertValidationType": (form.certificate_validation_type || '').toString(),
                "CertificateTransparencyLoggingPreference": (form.certificate_transparency_logging_preference || '').toString(),
                "godaddy_slot_size": (form.godaddy_slot_size || '').toString(),
                "issuer": (form.issuer || '').toString(),
                "region": (form.region || '').toString(),
                "ca_signing_algorithm": (form.ca_signing_algorithm || '').toString(),
                "sectigo_server_type": (form.sectigo_server_type || '').toString(),
                "assignment_group_name": (assignment_group_name || '').toString(),
                "cmdb_sync": (context.cmdb_sync || '').toString(),
                "push_to_end_device": (form.push_to_end_device || '').toString(),
                "push_assignment_group": (gr_clm.push_assignment_group || '').toString(),
                "send_certificate": (gr_clm.send_certificate_to_end_user || '').toString(),
                "vendor_name": (form.vendor_name || '').toString(),
                "device_name": (form.device_name || '').toString(),
                "profile_name": (profile_name || '').toString(),
                "time_zone": (gr_clm.time_zone || '').toString(),
                "push_root_and_intermediate_certificates": (form.push_root_and_intermediate_certificates || '').toString(),
                "push_certificate_format": (form.push_certificate_format || '').toString(),
                "customize_push_location": (form.customize_push_location || '').toString(),
                "private_key_in_device": (form.private_key_in_device || '').toString(),
                "intermediate_and_ca_certificate_directory": (form.intermediate_and_ca_certificate_directory || '').toString(),
                "certificate_directory": (form.certificate_directory || '').toString(),
                "key_directory": (form.key_directory || '').toString(),
                "keystore_location": (form.keystore_location || '').toString(),
                "keystore_password": (form.keystore_password || '').toString(),
                "service_restart": (form.service_restart || '').toString(),
                "private_key_location": (form.private_key_location || '').toString(),
                "catalog_task": (gr_clm.create_catalog_task_ticket || '').toString(),
                "domain_admin_email": (form.domain_admin_email || '').toString(),
                "business_category": (form.business_category || '').toString(),
                "incorporating_agency_reg_no": (form.incorporating_agency_reg_no || '').toString(),
                "designation": (form.designation || '').toString(),
                "globalsign_mssl_profile_name": (form.globalsign_mssl_profile_name || '').toString(),
                "globalsign_atlas_certificate_profile": (form.globalsign_atlas_certificate_profile || '').toString(),
                "avx_issuer_location": (form.avx_issuer_location || '').toString(),
                "avx_issuer_name": (form.avx_issuer_name || '').toString(),
                "organization_address": (form.organization_address || '').toString(),
                "csr_zip_code": (form.csr_zip_code || '').toString(),
                "form_assignment_group": (form.ticket_assignment_group.name || '').toString(),
                "zip_certificate_file": (gr_clm.zip_the_certificate_file || false).toString(),
                "digicert_mpki_profile_name": (form.digicert_mpki_profiles || '').toString(),
                "custom_attributes": (custom_cert_attr || []),
                "zip_trust_certificate": (gr_clm.attach_trust_cert || false).toString(),
                "division_id": (form.division_id || '').toString(),
                "swisssign_client_name": (form.swisssign_client_name || '').toString(),
                "avx_pki_native_issuer_location": (form.avx_pki_native_issuer_location || '').toString(),
                "endpoint": (form.endpoint || '').toString,
                "vendor_csr": (form.vendor_csr || '').toString(),
                "device_name_csr": (form.device_name_csr || '').toString(),
                "key_vault_name": (key_vault_name || '').toString(),
                "csr_location": (form.csr_location || '').toString()
            };

            var payload = helper.createPayload(gr_clm.workflow_name_for_create_appviewx, fieldInfo);
            return helper.submitWorkflow(context, payload, {
                startScript: 'create_certificate',
                requestScript: requestScript,
                successComment: true
            });
        } catch (error) {
            return helper.failWorkflow(context, {
                requestScript: requestScript,
                error: error
            });
        }
    },

    type: 'trigger_enroll_workflow'
};
